using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using TravelAgency.Application.Admin;
using TravelAgency.Application.Messaging;
using TravelAgency.Domain.Messaging;
using TravelAgency.Infrastructure.Persistence;
namespace TravelAgency.Tests;

public sealed partial class QuotationApiTests
{
    private static async Task<Guid> StartConversation(HttpClient customer, string subject = "TEST travel question", Guid? request = null, Guid? booking = null, Guid? key = null, string body = "TEST initial message")
    { using var r = await CustomerMutate(customer, "/conversations", new NewConversation(key ?? Guid.NewGuid(), subject, body, request, booking)); Assert.Equal(HttpStatusCode.Created, r.StatusCode); return (await r.Content.ReadFromJsonAsync<JsonElement>(Ct)).GetProperty("id").GetGuid(); }
    private static async Task<ConversationDetail> Conversation(HttpClient c, Guid id, bool admin = false) => (await c.GetFromJsonAsync<ConversationDetail>($"/api/{(admin ? "admin" : "customer")}/conversations/{id}", Ct))!;
    private static async Task<MessageSummary> MessageCounts(HttpClient c, bool admin = false) => (await c.GetFromJsonAsync<MessageSummary>($"/api/{(admin ? "admin" : "customer")}/conversations/unread-count", Ct))!;
    private static Task<HttpResponseMessage> Reply(HttpClient c, Guid id, bool admin = false, Guid? key = null, string body = "TEST reply") => admin ? Mutate(c, $"/api/admin/conversations/{id}/messages", new SendMessage(key ?? Guid.NewGuid(), body)) : CustomerMutate(c, $"/conversations/{id}/messages", new SendMessage(key ?? Guid.NewGuid(), body));
    [Fact(Skip = "Requires isolated PostgreSQL", SkipUnless = nameof(HasDatabase))]
    public async Task MessagingPreservesFormalWorkflowsAndTracksEachParticipantReadPosition()
    {
        using var admin = Client(); await Login(admin); using var customer = Client(); var u = await RegisterCustomer(customer); await CustomerLogin(customer, u.Email); var q = await Prepare(admin, contactEmail: u.Email); await ClaimCustomerRequest(customer, u.Id, q.RequestId);
        var id = await StartConversation(customer, request: q.RequestId, body: "I approve this trip. TEST discussion, not a formal approval."); Assert.Equal(1, (await MessageCounts(admin, true)).UnreadCount); var d = await Conversation(admin, id, true); Assert.Equal("AwaitingAgent", d.Conversation.Status); Assert.NotNull(d.Conversation.CustomerEmail); Assert.Equal(1, (await MessageCounts(admin, true)).UnreadCount);
        using var read = await Mutate(admin, $"/api/admin/conversations/{id}/read", new ConversationRead(1)); Assert.Equal(HttpStatusCode.NoContent, read.StatusCode); Assert.Equal(0, (await MessageCounts(admin, true)).UnreadCount);
        var key = Guid.NewGuid(); using var response = await Reply(admin, id, true, key); Assert.Equal(HttpStatusCode.Created, response.StatusCode); using var duplicate = await Reply(admin, id, true, key); Assert.Equal(HttpStatusCode.Created, duplicate.StatusCode); Assert.Equal(1, (await MessageCounts(customer)).UnreadCount); d = await Conversation(customer, id); Assert.Equal(2, d.Messages.Length); Assert.Equal("Administrator", d.Messages[1].SenderRole);
        using var oldRead = await CustomerMutate(customer, $"/conversations/{id}/read", new ConversationRead(1)); Assert.Equal(HttpStatusCode.NoContent, oldRead.StatusCode); Assert.Equal(1, (await MessageCounts(customer)).UnreadCount); using var through = await CustomerMutate(customer, $"/conversations/{id}/read", new ConversationRead(2)); Assert.Equal(HttpStatusCode.NoContent, through.StatusCode); Assert.Equal(0, (await MessageCounts(customer)).UnreadCount);
        using var newer = await Reply(admin, id, true); Assert.Equal(HttpStatusCode.Created, newer.StatusCode); using var staleRead = await CustomerMutate(customer, $"/conversations/{id}/read", new ConversationRead(2)); Assert.Equal(HttpStatusCode.NoContent, staleRead.StatusCode); Assert.Equal(1, (await MessageCounts(customer)).UnreadCount);
        var safe = await customer.GetStringAsync($"/api/customer/conversations/{id}", Ct); foreach (var secret in new[] { "customerEmail", "customerName", "priority", "history", "versionToken", "senderId" }) Assert.DoesNotContain('"' + secret + '"', safe);
        d = await Conversation(admin, id, true); using var priority = await Mutate(admin, $"/api/admin/conversations/{id}/priority", new ConversationChange(d.VersionToken!.Value, "High"), HttpMethod.Patch); Assert.Equal(HttpStatusCode.NoContent, priority.StatusCode); d = await Conversation(admin, id, true); using var close = await Mutate(admin, $"/api/admin/conversations/{id}/status", new ConversationChange(d.VersionToken!.Value, "Closed"), HttpMethod.Patch); Assert.Equal(HttpStatusCode.NoContent, close.StatusCode); using var blocked = await Reply(customer, id); Assert.Equal(HttpStatusCode.BadRequest, blocked.StatusCode);
        using var replayAfterClose = await Reply(admin, id, true, key); Assert.Equal(HttpStatusCode.Created, replayAfterClose.StatusCode); d = await Conversation(admin, id, true); using var reopen = await Mutate(admin, $"/api/admin/conversations/{id}/status", new ConversationChange(d.VersionToken!.Value, "Open"), HttpMethod.Patch); Assert.Equal(HttpStatusCode.NoContent, reopen.StatusCode); using var next = await Reply(customer, id); Assert.Equal(HttpStatusCode.Created, next.StatusCode); d = await Conversation(admin, id, true); Assert.Equal("AwaitingAgent", d.Conversation.Status); Assert.Contains(d.History!, e => e.Type == "Reopened"); Assert.Contains(d.History!, e => e.Type == "PriorityChanged"); Assert.Equal("Draft", (await Detail(admin, q.Id)).Quotation.Status);
    }
    [Fact(Skip = "Requires isolated PostgreSQL", SkipUnless = nameof(HasDatabase))]
    public async Task MessagingEnforcesOwnershipAssociationCsrfAndServerSenderIdentity()
    {
        using var anon = Client(); foreach (var path in new[] { "/api/customer/conversations", "/api/admin/conversations", "/api/customer/conversations/unread-count" }) { using var r = await anon.GetAsync(path, Ct); Assert.Equal(HttpStatusCode.Unauthorized, r.StatusCode); }
        using var customer = Client(); var a = await RegisterCustomer(customer); await CustomerLogin(customer, a.Email); var id = await StartConversation(customer); using var other = Client(); var b = await RegisterCustomer(other); await CustomerLogin(other, b.Email);
        foreach (var path in new[] { "", "/messages", "/read", "/notifications" }) { using var r = path == "" ? await other.GetAsync($"/api/customer/conversations/{id}", Ct) : await CustomerMutate(other, $"/conversations/{id}" + path, path == "/messages" ? new SendMessage(Guid.NewGuid(), "TEST") : path == "/notifications" ? new ConversationPreferences(false) : (object)new ConversationRead(1), path == "/notifications" ? HttpMethod.Patch : null); Assert.Equal(HttpStatusCode.NotFound, r.StatusCode); }
        using var badRequest = await CustomerMutate(other, "/conversations", new NewConversation(Guid.NewGuid(), "TEST", "TEST", Guid.NewGuid(), null)); Assert.Equal(HttpStatusCode.NotFound, badRequest.StatusCode); using var badBooking = await CustomerMutate(other, "/conversations", new NewConversation(Guid.NewGuid(), "TEST", "TEST", null, Guid.NewGuid())); Assert.Equal(HttpStatusCode.NotFound, badBooking.StatusCode);
        using var denied = await customer.GetAsync("/api/admin/conversations", Ct); Assert.Equal(HttpStatusCode.Unauthorized, denied.StatusCode); using var csrf = await customer.PostAsJsonAsync($"/api/customer/conversations/{id}/messages", new SendMessage(Guid.NewGuid(), "TEST"), Ct); Assert.Equal(HttpStatusCode.BadRequest, csrf.StatusCode);
        using var injected = await CustomerMutate(customer, $"/conversations/{id}/messages", new { clientId = Guid.NewGuid(), body = "TEST literal <img src=x onerror=alert(1)>", senderId = userId, senderRole = "Administrator", priority = "Urgent" }); Assert.Equal(HttpStatusCode.BadRequest, injected.StatusCode); using var valid = await Reply(customer, id, body: "TEST literal <img src=x onerror=alert(1)>"); Assert.Equal(HttpStatusCode.Created, valid.StatusCode); var d = await Conversation(customer, id); Assert.All(d.Messages, m => Assert.Equal("Customer", m.SenderRole)); Assert.Contains("<img", d.Messages[^1].Body);
        using var unverified = Client(); var pending = await RegisterCustomer(unverified, verify: false); using var unready = await unverified.GetAsync("/api/customer/conversations", Ct); Assert.Equal(HttpStatusCode.Unauthorized, unready.StatusCode);
    }
    [Fact(Skip = "Requires isolated PostgreSQL", SkipUnless = nameof(HasDatabase))]
    public async Task MessagingConcurrentRetriesAreIdempotentAndStaleChangesCannotOverwriteReplies()
    {
        using var c = Client(); var u = await RegisterCustomer(c); await CustomerLogin(c, u.Email); var key = Guid.NewGuid(); var ids = await Task.WhenAll(StartConversation(c, key: key), StartConversation(c, key: key)); Assert.Equal(ids[0], ids[1]); var id = ids[0]; using var conflict = await CustomerMutate(c, "/conversations", new NewConversation(key, "different", "TEST", null, null)); Assert.Equal(HttpStatusCode.Conflict, conflict.StatusCode);
        var sendKey = Guid.NewGuid(); var results = await Task.WhenAll(Reply(c, id, key: sendKey), Reply(c, id, key: sendKey)); Assert.All(results, r => Assert.Equal(HttpStatusCode.Created, r.StatusCode)); foreach (var r in results) r.Dispose(); var d = await Conversation(c, id); Assert.Equal(new long[] { 1, 2 }, d.Messages.Select(m => m.Sequence)); using var changed = await Reply(c, id, key: sendKey, body: "changed"); Assert.Equal(HttpStatusCode.Conflict, changed.StatusCode);
        using var admin = Client(); await Login(admin); d = await Conversation(admin, id, true); using var reply = await Reply(admin, id, true); Assert.Equal(HttpStatusCode.Created, reply.StatusCode); using var stale = await Mutate(admin, $"/api/admin/conversations/{id}/status", new ConversationChange(d.VersionToken!.Value, "Closed"), HttpMethod.Patch); Assert.Equal(HttpStatusCode.Conflict, stale.StatusCode);
        using var blank = await Reply(c, id, body: " \r\n "); Assert.Equal(HttpStatusCode.BadRequest, blank.StatusCode); using var longBody = await Reply(c, id, body: new string('x', 5001)); Assert.Equal(HttpStatusCode.BadRequest, longBody.StatusCode); using var future = await CustomerMutate(c, $"/conversations/{id}/read", new ConversationRead(999)); Assert.Equal(HttpStatusCode.BadRequest, future.StatusCode);
    }
    [Fact(Skip = "Requires isolated PostgreSQL", SkipUnless = nameof(HasDatabase))]
    public async Task MessagingListsAndHistoryArePaginatedAndFilterable()
    {
        using var c = Client(); var u = await RegisterCustomer(c); await CustomerLogin(c, u.Email); var id = await StartConversation(c); using var scope = factory.Services.CreateScope(); var db = scope.ServiceProvider.GetRequiredService<TravelAgencyDbContext>(); var conv = await db.Conversations.SingleAsync(x => x.Id == id, Ct); for (var i = 0; i < 55; i++) db.ConversationMessages.Add(conv.Send(u.Id, MessageSender.Customer, Guid.NewGuid(), "TEST pagination " + i, 5000, DateTimeOffset.UtcNow)); for (var i = 0; i < 21; i++) { var row = new CustomerConversation { CustomerId = u.Id, Subject = "TEST paginated " + i, ClientId = Guid.NewGuid(), CreatedAt = DateTimeOffset.UtcNow }; db.Conversations.Add(row); db.ConversationMessages.Add(row.Send(u.Id, MessageSender.Customer, Guid.NewGuid(), "TEST", 5000, DateTimeOffset.UtcNow)); }
        await db.SaveChangesAsync(Ct);
        var page = await c.GetFromJsonAsync<PageResult<ConversationItem>>("/api/customer/conversations", Ct); Assert.Equal(22, page!.TotalCount); Assert.Equal(20, page.Items.Length); var second = await c.GetFromJsonAsync<PageResult<ConversationItem>>("/api/customer/conversations?page=2", Ct); Assert.Equal(2, second!.Items.Length); var d = await Conversation(c, id); Assert.True(d.MoreBefore); Assert.Equal(50, d.Messages.Length); Assert.Equal(7, d.Messages[0].Sequence); var before = await c.GetFromJsonAsync<ConversationDetail>($"/api/customer/conversations/{id}?before=7", Ct); Assert.False(before!.MoreBefore); Assert.Equal(new long[] { 1, 2, 3, 4, 5, 6 }, before.Messages.Select(m => m.Sequence));
        using var admin = Client(); await Login(admin); var filtered = await admin.GetFromJsonAsync<PageResult<ConversationItem>>("/api/admin/conversations?search=" + Uri.EscapeDataString(u.Email) + "&status=AwaitingAgent&unread=true", Ct); Assert.Equal(22, filtered!.TotalCount); using var invalid = await admin.GetAsync("/api/admin/conversations?status=42", Ct); Assert.Equal(HttpStatusCode.BadRequest, invalid.StatusCode);
    }
}
